paragraph.math:
$$\begin{array}{l}
  {\nabla f\left( {x,y,z} \right) = \frac{\partial f}{\partial x}\mathbf{i} + \frac{\partial f}{\partial y}\mathbf{j} + \frac{\partial f}{\partial z}\mathbf{k}} \\
  {\phantom{\nabla f\left( {x,y,z} \right)} = \frac{- mMGx}{\left( {x^{2} + y^{2} + z^{2}} \right)^{3 \slash 2}}\mathbf{i} + \frac{- mMGy}{\left( {x^{2} + y^{2} + z^{2}} \right)^{3 \slash 2}}\mathbf{j} + \frac{- mMGz}{\left( {x^{2} + y^{2} + z^{2}} \right)^{3 \slash 2}}\mathbf{k}} \\
  {\phantom{\nabla f\left( {x,y,z} \right)} = \mathbf{F}\left( {x,y,z} \right)}
  \end{array}$$

$$\begin{array}{l}
  {{\int_{C}{{({2 + x^{2}y})}ds}} = {\int_{0}^{\pi}{{({2 + \cos^{2}‍t\sin t})}\sqrt{\left( \frac{dx}{dt} \right)^{2} + \left( \frac{dy}{dt} \right)^{2}}dt}}} \\
  {\phantom{\int_{C}{\left( {2 + x^{2}y} \right)ds}} = {\int_{0}^{\pi}{{({2 + \cos^{2}t\sin t})}\sqrt{\sin^{2}t + \cos^{2}‍t^{}}dt}}} \\
  {\phantom{\int_{C}{\left( {2 + x^{2}y} \right)ds}} = {\int_{0}^{\pi}{{({2 + \cos^{2}t\sin t})}dt = \left\lbrack \left. 2t - \frac{\cos^{3}t}{3} \right\rbrack \right._{0}^{\pi}}}} \\
  {\phantom{\int_{C}{\left( {2 + x^{2}y} \right)ds}} = 2\pi + \frac{2}{3}}
  \end{array}$$

$$\begin{matrix}
  {{\int_{C}{\mathbf{F} \cdot d\mathbf{r}}} = {\int_{a}^{b}{\mathbf{F}\left( {\mathbf{r}(t)} \right) \cdot \mathbf{r}^{\prime}(t)dt}}} \\
  {\phantom{\int_{C}{\mathbf{F} \cdot d\mathbf{r}}} = {\int_{a}^{b}{\left( {P\mathbf{i} + Q\mathbf{j} + R\mathbf{k}} \right) \cdot \left( {x^{\prime}(t)\mathbf{i} + y^{\prime}(t)\mathbf{j} + z^{\prime}(t)\mathbf{k}} \right)dt}}} \\
  {\phantom{\int_{C}{\mathbf{F} \cdot d\mathbf{r}}} = {\int_{a}^{b}\lbrack P\left( {x(t),y(t),z(t)} \right)x^{\prime}(t) + Q\left( {x(t),y(t),z(t)} \right)y^{\prime}(t)}} \\
  {\mspace{90mu}{\left. + R\left( {x(t),y(t),z(t)} \right)z^{\prime}(t) \right\rbrack dt}}
  \end{matrix}$$

$$\begin{array}{l}
  {W = {\int_{C}{\mathbf{F} \cdot d\mathbf{r} = {\int_{C}{\nabla f \cdot d\mathbf{r}}}}}} \\
  {\phantom{W} = f{({2,2,0})} - f{({3,4,12})}} \\
  {\phantom{W} = \frac{mMG}{\sqrt{2^{2} + 2^{2}}} - \frac{mMG}{\sqrt{3^{2} + 4^{2} + 12^{2}}} = mMG\left( {\frac{1}{2\sqrt{2}} - \frac{1}{13}} \right)}
  \end{array}$$

$$\begin{array}{l}
  {\int_{C}\mathbf{F} \cdot d\mathbf{r} = \int_{C_{1}}\mathbf{F} \cdot d\mathbf{r} = \int_{- 1}^{e^{\pi}}\mathbf{F}(\mathbf{r}(t)) \cdot \mathbf{r}^{\prime}(t)\mathit{dt}} \\
  {\phantom{\int_{C}\mathbf{F} \cdot d\mathbf{r}} = \int_{- 1}^{e^{\pi}}(3\mathbf{i} - 3t^{2}\mathbf{j}) \cdot ( - \mathbf{j})\mathit{dt}} \\
  {\phantom{\int_{C}\mathbf{F} \cdot d\mathbf{r}} = \int_{- 1}^{e^{\pi}}3t^{2}\mathit{dt} = t^{3}|_{- 1}^{e^{\pi}} = e^{3\pi} + 1}
  \end{array}$$

$$\begin{array}{l}
  {{\int_{C}x^{4}dx + xydy = \iint\limits_{D}\left( {\frac{\partial Q}{\partial x} - \frac{\partial P}{\partial y}} \right)dA} = {\int_{0}^{1}\int_{0}^{1 - x}(y - 0)dydx}} \\
  {\phantom{\int_{C}x^{4}dx + xydy} = {\int_{0}^{1}\left\lbrack {\frac{1}{2}y^{2}} \right\rbrack_{y = 0}^{y = 1 - x}dx = \frac{1}{2}\int_{0}^{1}{(1 - x)}^{2}dx}} \\
  {\phantom{\int_{C}x^{4}dx + xydy}{= - \frac{1}{6}{(1 - x)}^{3}\rbrack_{0}^{1} = \frac{1}{6}}}
  \end{array}$$

$$\begin{array}{l}
  {{\oint_{C}{(3y - e^{\sin x})}^{}dx} + {\left( {7x + \sqrt{y^{4} + 1}} \right)dy} = {\iint\limits_{D}\left\lbrack {\frac{\partial}{\partial x}\left( {7x + \sqrt{y^{4} + 1}} \right) - \frac{\partial}{\partial y}{({3y - e^{\sin x}})}} \right\rbrack dA}} \\
  {\phantom{{\oint_{C}{(3y - e^{\sin x})}^{}dx} + {{({7x + \sqrt{y^{4} + 1}})}dy}} = {\int_{0}^{2\pi}\int_{0}^{3}(7 - 3)rdrd\theta = 4\int_{0}^{2\pi}d\theta\int_{0}^{3}rdr = 36\pi}}
  \end{array}$$

$$\begin{array}{lll}
  {P(x,y) = 0} & {\quad P(x,y) = - y} & {\quad P(x,y) = - \frac{1}{2}y} \\
  {Q(x,y) = x} & {\quad Q(x,y) = 0} & {\quad Q(x,y) = \frac{1}{2}x}
  \end{array}$$

$$\begin{array}{l}
  {A = {\frac{1}{2}\int_{C}xdy - ydx}} \\
  {\phantom{A} = {\frac{1}{2}\int_{0}^{2\pi}(a\cos t)(b\cos t)dt - (b\sin t)( - a\sin t)dt}} \\
  {\phantom{A} = {\frac{ab}{2}\int_{0}^{2\pi}dt = \pi ab}}
  \end{array}$$

$$\begin{array}{r}
  {{\int_{C_{1} \cup C_{3}}{Pdx}} + {Qdy} = {\iint\limits_{D_{1}}\left( \frac{\partial Q}{\partial x} - \frac{\partial P}{\partial y} \right)dA}} \\
  {{\int_{C_{2} \cup ( - C_{3})}{Pdx}} + {Qdy} = {\iint\limits_{D_{2}}\left( \frac{\partial Q}{\partial x} - \frac{\partial P}{\partial y} \right)dA}}
  \end{array}$$

$$\begin{array}{l}
  {{\iint\limits_{D}{\left( {\frac{\partial Q}{\partial x} - \frac{\partial P}{\partial y}} \right)dA}} = {{\iint\limits_{D^{\prime}}{\left( {\frac{\partial Q}{\partial x} - \frac{\partial P}{\partial y}} \right)dA}} + {\iint\limits_{D^{''}}{\left( {\frac{\partial Q}{\partial x} - \frac{\partial P}{\partial y}} \right)dA}}}} \\
  {\phantom{\iint\limits_{D}{\left( {\frac{\partial Q}{\partial x} - \frac{\partial P}{\partial y}} \right)dA}} = {\int_{\partial D^{\prime}}Pdx + Qdy + \int_{\partial D^{''}}Pdx + Qdy}}
  \end{array}$$

$$\begin{array}{l}
  {{\int_{C}Pdx + Qdy + \int_{- C^{\prime}}Pdx + Qdy} = {{\iint\limits_{D}\left( {\frac{\partial Q}{\partial x} - \frac{\partial P}{\partial y}} \right)}dA}} \\
  {\phantom{\int_{C}Pdx + Qdy + \int_{- C^{\prime}}Pdx + Qdy} = {{\iint\limits_{D}\left\lbrack {\frac{y^{2} - x^{2}}{{(x^{2} + y^{2})}^{2}} - \frac{y^{2} - x^{2}}{{(x^{2} + y^{2})}^{2}}} \right\rbrack}dA = 0}}
  \end{array}$$

$$\begin{array}{l}
  {{\int_{C}{\mathbf{F} \cdot d\mathbf{r}}} = {{\int_{C}{\mathbf{F} \cdot d\mathbf{r}}} = {\int_{0}^{2\pi}{\mathbf{F}\left( \mathbf{r}(t) \right) \cdot \mathbf{r}^{\prime}(t)dt}}}} \\
  {\phantom{\int_{C}{F \cdot d\mathbf{r}}} = {{\int_{0}^{2\pi}\frac{( - a\sin t)( - a\sin t) + (a\cos t)(a\cos t)}{a^{2}\cos^{2}t + a^{2}\sin^{2}t}}dt = {\int_{0}^{2\pi}{dt = 2\pi}}}}
  \end{array}$$

$$\begin{array}{l}
  {{\nabla \times \mathbf{F}} = \left| \begin{matrix}
  \mathbf{i} & \mathbf{j} & \mathbf{k} \\
  \frac{\partial}{\partial x} & \frac{\partial}{\partial y} & \frac{\partial}{\partial z} \\
  P & Q & R
  \end{matrix} \right|} \\
  {\phantom{\nabla \times \mathbf{F}} = {\left( {\frac{\partial R}{\partial y} - \frac{\partial Q}{\partial z}} \right)\mathbf{i} + \left( {\frac{\partial P}{\partial z} - \frac{\partial R}{\partial x}} \right)\mathbf{j} + \left( {\frac{\partial Q}{\partial x} - \frac{\partial P}{\partial y}} \right)\mathbf{k}}} \\
  {\phantom{\nabla \times \mathbf{F}} = {{curl}\mathbf{F}}}
  \end{array}$$

$$\begin{array}{l}
  {{{curl}\mathbf{F}} = {\nabla \times \mathbf{F} = \left| \begin{matrix}
  \mathbf{i} & \mathbf{j} & \mathbf{k} \\
  \frac{\partial}{\partial x} & \frac{\partial}{\partial y} & \frac{\partial}{\partial z} \\
  {xz} & {xyz} & {- y^{2}}
  \end{matrix} \right|}} \\
  {\phantom{{curl}\mathbf{F}} = {\left\lbrack {\frac{\partial}{\partial y}( - y^{2}) - \frac{\partial}{\partial z}(xyz)} \right\rbrack\mathbf{i} - \left\lbrack {\frac{\partial}{\partial x}( - y^{2}) - \frac{\partial}{\partial z}(xz)} \right\rbrack\mathbf{j}}} \\
  {\phantom{{{curl}\mathbf{F}} = \left\lbrack \frac{\partial}{\partial y} \right.} + \left\lbrack {\frac{\partial}{\partial x}(xyz) - \frac{\partial}{\partial y}(xz)} \right\rbrack\mathbf{k}} \\
  {\phantom{{curl}\mathbf{F}} = {( - 2y - xy)\mathbf{i} - (0 - x)\mathbf{j} + (yz - 0)\mathbf{k}}} \\
  {\phantom{{curl}\mathbf{F}} = {- y(2 + x)\mathbf{i} + x\mathbf{j} + yz\mathbf{k}}}
  \end{array}$$

$$\begin{array}{l}
  {\oint_{C}{\mathbf{F} \cdot \mathbf{n}ds = {\int_{a}^{b}{\left( {\mathbf{F} \cdot \mathbf{n}} \right)(t)\left| {\mathbf{r}^{\prime}(t)} \right|dt}}}} \\
  {\phantom{\oint_{C}{\mathbf{F} \cdot \mathbf{n}ds}}{= {\int_{a}^{b}{\left\lbrack {\frac{P{({x(t),y(t)})}y^{\prime}(t)}{\left| {\mathbf{r}^{\prime}(t)} \right|} - \frac{Q{({x(t),y(t)})}x^{\prime}(t)}{\left| {\mathbf{r}^{\prime}(t)} \right|}} \right\rbrack\left| {\mathbf{r}^{\prime}(t)} \right|dt}}}} \\
  {\phantom{\oint_{C}{\mathbf{F} \cdot \mathbf{n}ds}}{= {\int_{a}^{b}{P{({x(t),y(t)})}y^{\prime}(t)dt - Q\left( {x(t),y(t)} \right)x^{\prime}(t)dt}}}} \\
  {\phantom{\oint_{C}{\mathbf{F} \cdot \mathbf{n}ds}}{= {\int_{C}{Pdy - Qdx = {\iint\limits_{D}{\left( {\frac{\partial P}{\partial x} + \frac{\partial Q}{\partial y}} \right)dA}}}}}}
  \end{array}$$

$$\begin{array}{l}
  {\mathbf{r}_{u} = \frac{\partial x}{\partial u}\mathbf{i} + \frac{\partial y}{\partial u}\mathbf{j} + \frac{\partial z}{\partial u}\mathbf{k} = 2u\mathbf{i} + \mathbf{k}} \\
  {\mathbf{r}_{\upsilon} = \frac{\partial x}{\partial\upsilon}\mathbf{i} + \frac{\partial y}{\partial\upsilon}\mathbf{j} + \frac{\partial z}{\partial\upsilon}\mathbf{k} = 2\upsilon\mathbf{j} + 2\mathbf{k}}
  \end{array}$$

$$\begin{array}{l}
  {\mathbf{r}_{\phi} \times \mathbf{r}_{\theta} = \left| \begin{matrix}
  \mathbf{i} & \mathbf{j} & \mathbf{k} \\
  \frac{\partial x}{\partial\phi} & \frac{\partial y}{\partial\phi} & \frac{\partial z}{\partial\phi} \\
  \frac{\partial x}{\partial\theta} & \frac{\partial y}{\partial\theta} & \frac{\partial z}{\partial\theta}
  \end{matrix} \right| = \left| \begin{matrix}
  \mathbf{i} & \mathbf{j} & \mathbf{k} \\
  {a\cos\phi\cos\theta} & {a\cos\phi\sin\theta} & {- a\sin\phi} \\
  {- a\sin\phi\sin\theta} & {a\sin\phi\cos\theta} & 0
  \end{matrix} \right|} \\
  {\phantom{\mathbf{r}_{\phi} \times \mathbf{r}_{\theta}}{= a^{2}\sin^{2}\phi\cos\theta\mathbf{i} + a^{2}\sin^{2}\phi\sin\theta\mathbf{j} + a^{2}\sin\phi\cos\phi\mathbf{k}}}
  \end{array}$$

$$\begin{array}{l}
  {\left| {\mathbf{r}_{\phi} \times \mathbf{r}_{\theta}} \right| = \sqrt{a^{4}{\sin}^{4}\phi{\cos}^{2}\theta + a^{4}{\sin}^{4}\phi{\sin}^{2}\theta + a^{4}{\sin}^{2}\phi{\cos}^{2}\phi^{}}} \\
  {\phantom{\left| {r_{\phi} \times r_{\theta}} \right|}{= \sqrt{a^{4}{\sin}^{4}\phi + a^{4}{\sin}^{2}\phi{\cos}^{2}\phi^{}} = a^{2}\sqrt{{\sin}^{2}\phi^{}} = a^{2}\sin\phi}}
  \end{array}$$

$$\begin{array}{l}
  {|\mathbf{r}_{x} \times \mathbf{r}_{\theta}| = \sqrt{{\lbrack f(x)\rbrack}^{2}{\lbrack f^{\prime}(x)\rbrack}^{2} + {\lbrack f(x)\rbrack}^{2}\cos^{2}\theta + {\lbrack f(x)\rbrack}^{2}\sin^{2}\theta}} \\
  {\phantom{\left| r_{x} \times r_{\theta} \right|} = \sqrt{\left\lbrack {f(x)} \right\rbrack^{2}\left\lbrack {1 + \left\lbrack {f^{\prime}(x)} \right\rbrack^{2}} \right\rbrack^{}} = f(x)\sqrt{1 + \left\lbrack {f^{\prime}(x)} \right\rbrack^{2}}}
  \end{array}$$

$$\begin{array}{l}
  {\iint\limits_{S_{3}}{zdS = {\iint\limits_{D}{\left( {1 + x} \right)\sqrt{1 + \left( \frac{\partial z}{\partial x} \right)^{2} + \left( \frac{\partial z}{\partial y} \right)^{2}}dA}}}} \\
  {\phantom{\iint\limits_{S_{3}}{zdS}} = {\int_{0}^{2\pi}{\int_{0}^{1}{\left( {1 + r\cos\theta} \right)\sqrt{1 + 1 + 0}rdrd\theta}}}} \\
  {\phantom{\iint\limits_{S_{3}}{zdS}} = \sqrt{2}{\int_{0}^{2\pi}{\int_{0}^{1}{{({r + r^{2}\cos\theta})}drd\theta}}} = \sqrt{2}{\int_{0}^{2\pi}{{\left( {\frac{1}{2} + \frac{1}{3}\cos\theta} \right)}d\theta}}} \\
  {\phantom{\iint\limits_{S_{3}}{zdS}} = \sqrt{2}\left\lbrack {\frac{\theta}{2} + \frac{\sin\theta}{3}} \right\rbrack_{0}^{2\pi} = \sqrt{2}\pi}
  \end{array}$$

$${curl}\mathbf{F} = \left| \begin{matrix}
  \mathbf{i} & \mathbf{j} & \mathbf{k} \\
  \frac{\partial}{\partial x} & \frac{\partial}{\partial y} & \frac{\partial}{\partial z} \\
  {- y^{2}} & x & z^{2}
  \end{matrix} \right| = \left( {1 + 2y} \right)\mathbf{k}$$

$$\begin{array}{l}
  {\iint\limits_{S}{{curl}\mathbf{F} \cdot d\mathbf{S} = {\int_{C}{\mathbf{F} \cdot d\mathbf{r} = {\int_{0}^{2\pi}{\mathbf{F}\left( {\mathbf{r}(t)} \right) \cdot \mathbf{r}^{\prime}(t)dt}}}}}} \\
  {{\phantom{\iint\limits_{S}{{curl}\mathbf{F} \cdot d\mathbf{S}}} = {\int_{0}^{2\pi}{{({- \sqrt{3}\cos t\sin t + \sqrt{3}\sin t\cos t})}dt}}} = \sqrt{3}{\int_{0}^{2\pi}{0dt = 0}}}
  \end{array}$$

$$\begin{array}{l}
  {\int_{C_{a}}\mathbf{v} \cdot d\mathbf{r} = {\iint\limits_{S_{a}}{{curl}\mathbf{v} \cdot d\mathbf{S} = {\iint\limits_{S_{a}}{{curl}\mathbf{v} \cdot \mathbf{n}dS}}}}} \\
  {\phantom{\int_{C_{a}}\mathbf{v} \cdot d\mathbf{r}} \approx {\iint\limits_{S_{a}}{{curl}\mathbf{v}\left( P_{0} \right) \cdot \mathbf{n}\left( P_{0} \right)dS = {curl}\mathbf{v}\left( P_{0} \right) \cdot \mathbf{n}\left( P_{0} \right)\pi a^{2}}}}
  \end{array}$$

$$\begin{array}{l}
  {\iint\limits_{S}{\mathbf{F} \cdot d\mathbf{S}} = \iiint\limits_{E}{div}\mathbf{F}dV = \iiint\limits_{E}3ydV} \\
  {\phantom{\iint\limits_{S}{\mathbf{F} \cdot d\mathbf{S}}}{= 3\int_{- 1}^{1}}\int_{0}^{1 - x^{2}}\int_{0}^{2 - z}{ydydzdx} = 3\int_{- 1}^{1}{\int_{0}^{1 - x^{2}}\frac{{(2 - z)}^{2}}{2}dzdx}} \\
  {\phantom{\iint\limits_{S}{\mathbf{F} \cdot d\mathbf{S}}}{= \frac{3}{2}}\int_{- 1}^{1}\left\lbrack {- \frac{{({2 - z})}^{3}}{3}} \right\rbrack_{0}^{1 - x^{2}}dx = - \frac{1}{2}{\int_{- 1}^{1}{{\lbrack{{({x^{2} + 1})}^{3} - 8}\rbrack}dx}}} \\
  {\phantom{\iint\limits_{S}{\mathbf{F} \cdot d\mathbf{S}}}{= - {\int_{0}^{1}{{({x^{6} + 3x^{4} + 3x^{2} - 7})}dx = \frac{184}{35}}}}}
  \end{array}$$
